const response = $json;
const testRecord = $('Select Test Record').first().json;

// Handle HTTP error responses
if (response.error || response.status >= 400) {
  return [{ json: {
    parse_ok: false,
    parse_method: 'primary_json',
    repair_used: false,
    processing_status: 'technical_error_candidate',
    parse_error: 'HTTP error: ' + JSON.stringify(response.error || response.status),
    raw_response_preview: JSON.stringify(response).substring(0, 800),
    original_record: testRecord
  }}];
}

// Find text item
let textItem;
try {
  if (!response.content || !Array.isArray(response.content)) throw new Error('No content array');
  textItem = response.content.find(c => c.type === 'text');
} catch(e) {
  return [{ json: {
    parse_ok: false, parse_method: 'primary_json', repair_used: false,
    processing_status: 'technical_error_candidate',
    parse_error: 'No content array: ' + e.message,
    raw_response_preview: JSON.stringify(response).substring(0, 800),
    original_record: testRecord
  }}];
}

if (!textItem || !textItem.text) {
  return [{ json: {
    parse_ok: false, parse_method: 'primary_json', repair_used: false,
    processing_status: 'technical_error_candidate',
    parse_error: 'No text item in content array',
    raw_response_preview: JSON.stringify(response.content || response).substring(0, 800),
    original_record: testRecord
  }}];
}

const rawPreview = textItem.text.substring(0, 1200);

// Parse with defensive cleanup
let parsed;
try {
  let txt = textItem.text.trim();
  txt = txt.replace(/^```json\s*/i, '').replace(/\s*```$/,'').trim();
  txt = txt.replace(/^```\s*/,'').replace(/\s*```$/,'').trim();
  const bStart = txt.indexOf('{');
  const bEnd = txt.lastIndexOf('}');
  if (bStart !== -1 && bEnd !== -1) txt = txt.substring(bStart, bEnd + 1);
  txt = txt.replace(/[\u2018\u2019]/g, "'").replace(/[\u201C\u201D\u00AB\u00BB]/g, '"');
  parsed = JSON.parse(txt);
} catch(e) {
  return [{ json: {
    parse_ok: false, parse_method: 'primary_json', repair_used: false,
    processing_status: 'technical_error_candidate',
    parse_error: 'JSON.parse failed: ' + e.message,
    raw_response_preview: rawPreview,
    original_record: testRecord
  }}];
}

return [{ json: {
  parse_ok: true,
  parse_method: 'primary_json',
  repair_used: false,
  repair_status: '',
  parse_error: '',
  raw_response_preview: rawPreview,
  ...parsed
}}];

const input = $json;
const testRecord = $('Select Test Record').first().json;

const rawPreview = input.raw_response_preview || input.original_record?.raw_response_preview || 'empty';
const parseErr = input.parse_error || 'Primary API bypassed (mock mode)';

const repairSystem = `You are a JSON repair formatter. Convert the provided raw model response into one strict JSON object matching the schema below. Rules:
- Do not add new facts. Do not invent contacts, regions, scores, or terms.
- Extract only what is explicitly stated in the raw response.
- If a value is unknown use empty string for text fields and 1 for score fields.
- If the raw response contains no useful market facts at all: return status=skipped, entity_type=irrelevant, recommended_action=ignore, all scores=1.
- Return JSON only. No markdown. No explanation. First char must be {, last must be }.
Schema fields required: created_at, source_type, platform, source_url, parsed_at, published_at, freshness_status, entity_type, company_name, profile_name, profile_url, region, service_type, offer_text, terms, contact_public, text_context, detected_need, competitor_strength, lead_signal_score, content_idea_score, quality_score, reason, recommended_action, status.
Enum values: entity_type=[competitor,lead_signal,market_signal,content_idea,irrelevant]; recommended_action=[monitor,contact,create_content,ignore,investigate]; status=[analyzed,skipped]; freshness_status=[fresh,recent,old,unknown].`;

const userMsg = JSON.stringify({
  original_record: {
    source_type: testRecord.source_type || '',
    platform: testRecord.platform || '',
    source_url: testRecord.source_url || '',
    published_at: testRecord.published_at || '',
    parsed_at: testRecord.parsed_at || ''
  },
  raw_primary_response: rawPreview,
  parse_error: parseErr,
  instruction: 'Convert raw_primary_response into the required JSON schema. Return JSON only.'
});

return [{ json: {
  model: 'claude-sonnet-4-6',
  max_tokens: 900,
  temperature: 0.0,
  system: repairSystem,
  messages: [{ role: 'user', content: userMsg }]
}}];

const response = $json;
const testRecord = $('Select Test Record').first().json;
const mockMode = testRecord.mock_mode || 'none';

// Test E: force technical_error for mock_unrepairable
if (mockMode === 'mock_unrepairable') {
  return [{ json: {
    parse_ok: false,
    parse_method: 'repaired_json',
    repair_used: true,
    repair_status: 'failed',
    processing_status: 'technical_error',
    route: 'technical_errors',
    needs_manual_review: true,
    parse_error: 'Simulated unrepairable response — forced technical_error for Test E',
    raw_response_preview: testRecord.raw_response_preview || '%%%% unrepairable %%%%',
    test_id: testRecord.test_id,
    expected_route: testRecord.expected_route,
    expected_entity_type: testRecord.expected_entity_type,
    expected_recommended_action: testRecord.expected_recommended_action,
    expected_quality_range: testRecord.expected_quality_range,
    test_pass_basic: true,
    test_notes: 'mock_unrepairable forced technical_error as expected'
  }}];
}

// Handle HTTP error from repair call
if (response.error || response.status >= 400) {
  return [{ json: {
    parse_ok: false, parse_method: 'repaired_json', repair_used: true,
    repair_status: 'failed', processing_status: 'technical_error', route: 'technical_errors',
    needs_manual_review: true,
    parse_error: 'Repair HTTP error: ' + JSON.stringify(response.error || response.status),
    raw_response_preview: JSON.stringify(response).substring(0, 500)
  }}];
}

// Find text item
let textItem;
try {
  textItem = (response.content || []).find(c => c.type === 'text');
} catch(e) { textItem = null; }

if (!textItem || !textItem.text) {
  return [{ json: {
    parse_ok: false, parse_method: 'repaired_json', repair_used: true,
    repair_status: 'failed', processing_status: 'technical_error', route: 'technical_errors',
    needs_manual_review: true,
    parse_error: 'No text item in repair response',
    raw_response_preview: JSON.stringify(response.content || response).substring(0, 500)
  }}];
}

const rawPreview = textItem.text.substring(0, 1200);

let parsed;
try {
  let txt = textItem.text.trim();
  txt = txt.replace(/^```json\s*/i,'').replace(/\s*```$/,'').trim();
  txt = txt.replace(/^```\s*/,'').replace(/\s*```$/,'').trim();
  const bStart = txt.indexOf('{'); const bEnd = txt.lastIndexOf('}');
  if (bStart !== -1 && bEnd !== -1) txt = txt.substring(bStart, bEnd + 1);
  txt = txt.replace(/[\u2018\u2019]/g,"'").replace(/[\u201C\u201D\u00AB\u00BB]/g,'"');
  parsed = JSON.parse(txt);
} catch(e) {
  return [{ json: {
    parse_ok: false, parse_method: 'repaired_json', repair_used: true,
    repair_status: 'failed', processing_status: 'technical_error', route: 'technical_errors',
    needs_manual_review: true,
    parse_error: 'Repair JSON.parse failed: ' + e.message,
    raw_response_preview: rawPreview
  }}];
}

const parseMethod = (mockMode === 'mock_markdown') ? 'mock_markdown_repair' : 'repaired_json';

return [{ json: {
  parse_ok: true,
  parse_method: parseMethod,
  repair_used: true,
  repair_status: 'success',
  parse_error: '',
  raw_response_preview: rawPreview,
  ...parsed
}}];

const data = $json;
const testRecord = $('Select Test Record').first().json;

function clamp(v) { const n = parseInt(v); return isNaN(n) ? 1 : Math.min(100, Math.max(1, n)); }

// Normalize free-text service_type into allowed enum values
function normalizeServiceType(raw, hay) {
  const allowed = ['secured_auto_loan','secured_real_estate_loan','pts_loan','refinancing','mortgage_adjacent','generic_lending'];
  const r = (raw || '').toLowerCase().trim();
  if (allowed.includes(r)) return r;
  const s = r + ' ' + (hay || '');
  if (s.includes('птс') || s.includes('pts')) return 'pts_loan';
  if ((s.includes('авто') || s.includes('машин')) && (s.includes('залог') || s.includes('collateral') || s.includes('ломбард'))) return 'secured_auto_loan';
  if (s.includes('недвиж') || s.includes('квартир') || s.includes('дом') || s.includes('земл')) return 'secured_real_estate_loan';
  if (s.includes('рефинанс') || s.includes('refinanc')) return 'refinancing';
  if (s.includes('ипотек') || s.includes('mortgage')) return 'mortgage_adjacent';
  if (s.includes('бизнес') || s.includes('business')) {
    if (s.includes('недвиж') || s.includes('квартир')) return 'secured_real_estate_loan';
    return 'generic_lending';
  }
  return 'unknown';
}

// Descriptive company_name fallback (never invent a brand)
function companyNameFallback(existing, entity, hay) {
  if (existing && String(existing).trim() !== '') return existing;
  if (entity === 'competitor' && (hay.includes('мфо') || hay.includes('микрофинанс') || hay.includes('mfo'))) return 'МФО / частный кредитор';
  if (hay.includes('частный инвестор')) return 'Частный инвестор';
  if (hay.includes('автоломбард')) return 'Автоломбард';
  if (hay.includes('брокер')) return 'Брокер';
  if (entity === 'competitor') return 'Конкурент без бренда';
  return '';
}

// Pass-through for confirmed technical_error (from Parse Repaired JSON)
if (data.processing_status === 'technical_error' && data.route === 'technical_errors') {
  const expRoute = testRecord.expected_route || '';
  return [{ json: {
    ...data,
    created_at: data.created_at || testRecord.parsed_at || '',
    source_type: data.source_type || testRecord.source_type || '',
    platform: data.platform || testRecord.platform || '',
    source_url: data.source_url || testRecord.source_url || '',
    parsed_at: data.parsed_at || testRecord.parsed_at || '',
    published_at: data.published_at || testRecord.published_at || '',
    test_id: testRecord.test_id,
    expected_route: testRecord.expected_route,
    expected_entity_type: testRecord.expected_entity_type,
    expected_recommended_action: testRecord.expected_recommended_action,
    expected_quality_range: testRecord.expected_quality_range,
    actual_entity_type: data.entity_type || '',
    actual_recommended_action: data.recommended_action || '',
    actual_quality_score: data.quality_score || 1,
    actual_lead_signal_score: data.lead_signal_score || 1,
    actual_content_idea_score: data.content_idea_score || 1,
    actual_competitor_strength: data.competitor_strength || 1,
    test_pass_basic: data.test_pass_basic !== undefined ? data.test_pass_basic : (data.route === expRoute),
    test_notes: data.test_notes || ('route=' + data.route + '; expected=' + expRoute)
  }}];
}

// Normalize schema fields
const entity = data.entity_type || 'irrelevant';
const status = data.status || 'analyzed';
const recAction = data.recommended_action || 'ignore';
const leadScore = clamp(data.lead_signal_score);
const compScore = clamp(data.competitor_strength);
const contentScore = clamp(data.content_idea_score);
const qualScore = clamp(data.quality_score);

const validEntities = ['competitor','lead_signal','market_signal','content_idea','irrelevant'];
const validActions = ['monitor','contact','create_content','ignore','investigate'];
const safeEntity = validEntities.includes(entity) ? entity : 'irrelevant';
const safeAction = validActions.includes(recAction) ? recAction : 'ignore';
const safeStatus = (status === 'skipped') ? 'skipped' : 'analyzed';

// Derived text haystacks for normalization and routing keyword checks
const hay = ((data.text_context||'') + ' ' + (data.offer_text||'') + ' ' + (data.detected_need||'') + ' ' + (data.reason||'') + ' ' + (data.service_type||'') + ' ' + (testRecord.text_context||'')).toLowerCase();
const companyHay = ((data.text_context||'') + ' ' + (data.reason||'') + ' ' + (data.offer_text||'') + ' ' + (data.source_url||testRecord.source_url||'') + ' ' + (data.detected_need||'')).toLowerCase();

const safeServiceType = normalizeServiceType(data.service_type, hay);
const safeCompanyName = companyNameFallback(data.company_name, safeEntity, companyHay);

// Determine processing_status
let procStatus = 'parsed_success';
if (safeStatus === 'skipped' || safeEntity === 'irrelevant') procStatus = 'business_skip';

// Weak / potential lead detection (must run before content_queue routing)
const srcType = (data.source_type || testRecord.source_type || '').toLowerCase();
const isSocialOrClassified = (srcType === 'social' || srcType === 'classified');
const productTerms = ['loan','collateral','pts','auto','real estate','refinanc','займ','кредит','залог','птс','авто','машин','недвиж','квартир','земл','рефинанс','ипотек'];
const mentionsProduct = productTerms.some(t => hay.includes(t));

const weakLead = (
  (safeEntity === 'lead_signal' && leadScore >= 30 && leadScore <= 69) ||
  (safeAction === 'investigate') ||
  (leadScore >= 30 && isSocialOrClassified && mentionsProduct) ||
  (safeEntity === 'content_idea' && leadScore >= 30 && isSocialOrClassified && safeServiceType !== 'unknown')
);

// Routing priority:
// 1 technical_errors (handled above) 2 skipped/irrelevant 3 hot lead 4 weak lead
// 5 competitor 6 pure content idea 7 fallback review_queue
let route;
let needsReview;

if (safeStatus === 'skipped' || safeEntity === 'irrelevant') {
  route = 'skipped_log'; needsReview = false;
} else if (safeEntity === 'lead_signal' && leadScore >= 70 && safeAction === 'contact') {
  route = 'results'; needsReview = false;
} else if (weakLead) {
  route = 'review_queue'; needsReview = true;
} else if (safeEntity === 'competitor' && compScore >= 45) {
  route = 'monitor_queue'; needsReview = false;
} else if (safeEntity === 'content_idea' && contentScore >= 50) {
  route = 'content_queue'; needsReview = true;
} else {
  route = 'review_queue'; needsReview = true;
}

// Safety: enforce route is exactly one of the six valid sheet tabs
const validRoutes = ['results','review_queue','monitor_queue','content_queue','skipped_log','technical_errors'];
let parseError = data.parse_error || '';
if (!validRoutes.includes(route)) {
  route = 'technical_errors';
  procStatus = 'technical_error';
  needsReview = true;
  parseError = (parseError ? parseError + '; ' : '') + 'invalid_route';
}

const expRoute = testRecord.expected_route || '';
const expEntity = testRecord.expected_entity_type || 'any';

// Test pass logic: route-focused for review_queue (entity may legitimately
// differ after repair); strict entity match for other routes
let testPass;
if (expRoute === 'review_queue') {
  testPass = (route === 'review_queue') && (needsReview === true) && (leadScore >= 30);
} else {
  testPass = (route === expRoute) && (expEntity === 'any' || safeEntity === expEntity);
}

return [{ json: {
  created_at: data.created_at || testRecord.parsed_at || '',
  source_type: data.source_type || testRecord.source_type || '',
  platform: data.platform || testRecord.platform || '',
  source_url: data.source_url || testRecord.source_url || '',
  parsed_at: data.parsed_at || testRecord.parsed_at || '',
  published_at: data.published_at || testRecord.published_at || '',
  freshness_status: data.freshness_status || 'unknown',
  entity_type: safeEntity,
  company_name: safeCompanyName,
  profile_name: data.profile_name || '',
  profile_url: data.profile_url || testRecord.profile_url || '',
  region: data.region || '',
  service_type: safeServiceType,
  offer_text: data.offer_text || '',
  terms: data.terms || '',
  contact_public: data.contact_public || '',
  text_context: data.text_context || '',
  detected_need: data.detected_need || '',
  competitor_strength: compScore,
  lead_signal_score: leadScore,
  content_idea_score: contentScore,
  quality_score: qualScore,
  reason: data.reason || '',
  recommended_action: safeAction,
  status: safeStatus,
  processing_status: procStatus,
  parse_method: data.parse_method || 'primary_json',
  parse_error: parseError,
  raw_response_preview: data.raw_response_preview || '',
  route: route,
  needs_manual_review: needsReview,
  source_record_type: testRecord.source_type || '',
  repair_used: data.repair_used || false,
  repair_status: data.repair_status || '',
  test_id: testRecord.test_id,
  expected_route: testRecord.expected_route,
  expected_entity_type: testRecord.expected_entity_type,
  expected_recommended_action: testRecord.expected_recommended_action,
  expected_quality_range: testRecord.expected_quality_range,
  actual_entity_type: safeEntity,
  actual_recommended_action: safeAction,
  actual_quality_score: qualScore,
  actual_lead_signal_score: leadScore,
  actual_content_idea_score: contentScore,
  actual_competitor_strength: compScore,
  test_pass_basic: testPass,
  test_notes: 'route=' + route + '; entity=' + safeEntity + '; lead=' + leadScore + '; comp=' + compScore + '; content=' + contentScore + '; action=' + safeAction + '; service=' + safeServiceType + '; company=' + safeCompanyName + '; weakLead=' + weakLead + '; parse=' + (data.parse_method || '') + '; repair=' + (data.repair_used || false) + '; expected_route=' + expRoute
}}];
